      "caution": "Le verre indiqué est en résine. Aucune valeur d'étanchéité en bar n'est documentée ici : vérifiez les usages autorisés.",
      "facts": [
        "caseSize",
        "glass"
      ]
    },
    "casio-mdv107": {
      "strength": "Les dimensions 49,5 × 44,2 × 12,1 mm et l'indication 20 bar caractérisent une montre d'allure plongeuse.",
      "usage": "À explorer si vous appréciez les index lisibles et une esthétique de plongée, avec un mouvement quartz.",
      "caution": "Les 44,2 mm correspondent à une largeur et non à un diamètre confirmé. L'indice 20 bar ne remplace pas la notice.",
      "facts": [
        "caseSize",
        "glass",
        "waterResistance"
      ]
    },
    "casio-ltp1302": {
      "strength": "Le cadran clair et le diamètre documenté de 30,2 mm composent une proposition discrète, avec les dimensions complètes du boîtier.",
      "usage": "Une piste pour une montre analogique de petit format et un fonctionnement à quartz.",
      "caution": "Un petit diamètre ne garantit pas un bon ajustement. Vérifiez longueur de bracelet, forme des cornes et porté réel.",
      "facts": [
        "diameter",
        "caseSize",
        "movement"
      ]
