    "swatch-clearly": {
      "strength": "Le boîtier transparent et les touches de couleur privilégient une expression graphique plutôt que des codes horlogers traditionnels.",
      "usage": "À regarder si la transparence est votre critère principal et que vous préférez le fonctionnement quartz.",
      "caution": "Le diamètre et le type de verre ne figurent pas dans nos données vérifiées. Vérifiez l'usage de l'indice 3 bar.",
      "facts": [
        "movement",
        "waterResistance"
      ]
    },
    "citizen-eco": {
      "strength": "Le mouvement Citizen Eco-Drive J800 fonctionne avec l'énergie lumineuse, dans une montre de 40 mm au cadran noir.",
