/* Atelier Montres / Édition photographique.
   Original art direction based on existing exact-reference authorized packshots.
   Reference research: Tissot product galleries, Chrono24 browsing, star-list:
   Recent, Awwwards, 60fps.design. No third-party CSS/imagery copied. */

.aff-hero{position:relative;background:
 radial-gradient(ellipse 50% 65% at 79% 34%,#3f5b477c,transparent 77%),
 linear-gradient(136deg,#10241b 4%,#20392c 64%,#17271e);isolation:isolate}
.aff-hero:before{content:"ATELIER";position:absolute;inset:auto -2% -6% auto;
 color:#f8f1db08;font:400 clamp(130px,22vw,320px)/1 Georgia,serif;
 pointer-events:none;letter-spacing:-.055em;white-space:nowrap}
.aff-hero .aff-copy{padding-bottom:115px}
.aff-hero .aff-copy>p:not(.overline):not(.aff-note){max-width:560px}
.am-hero-art{position:relative;height:685px;isolation:isolate;--photo-halo:#dfcfaa28}
.am-hero-art[data-editorial-tone="jade"]{--photo-halo:#bde7cb36}
.am-hero-art[data-editorial-tone="blue"]{--photo-halo:#a1c7e43f}
.am-hero-art[data-editorial-tone="ivory"]{--photo-halo:#efddaa45}
.am-hero-art[data-editorial-tone="steel"]{--photo-halo:#d8e4e74a}
.am-hero-art:before{content:"";position:absolute;inset:9% 7% 16%;
 border:1px solid #d8bd8a20;border-radius:50%;
 background:radial-gradient(circle at 50% 46%,var(--photo-halo),transparent 67%);
 box-shadow:0 0 0 58px #e9d9ac08,0 0 0 110px #e9d9ac03;
 pointer-events:none;transition:background .35s ease}
.am-hero-art .am-stage-halo{display:none}
.am-hero-art .am-hero-watch{z-index:1;position:absolute;top:22px;left:0;width:100%;height:495px;margin:0;transform:none;filter:none}
.am-hero-art .am-hero-watch img.am-hero-real-photo{width:100%;height:100%;object-fit:contain;
 mix-blend-mode:normal;border:1px solid #e3dac9;box-shadow:0 19px 55px #08170e5c;filter:drop-shadow(17px 22px 18px #0004);
 transition:opacity .22s ease,transform .35s ease}
.am-hero-art .am-hero-watch svg{height:95%;width:min(100%,450px)}
.am-hero-loading{font:500 12px/1.7 system-ui,sans-serif;letter-spacing:.07em;color:#d7e2d2;background:#132c2088;padding:14px 19px;border:1px solid #a2b59b33}
.am-hero-art .am-hero-label{z-index:2;bottom:106px;right:0;text-align:left;max-width:min(385px,80%);min-width:255px;box-sizing:border-box;padding:14px 18px 13px;background:linear-gradient(125deg,#122b22f3,#163628eb);border:1px solid #cbb38769;box-shadow:0 14px 44px #08191085;backdrop-filter:blur(5px)}
.am-hero-art .am-hero-label strong{font-size:clamp(16px,1.8vw,22px);letter-spacing:.065em}
.am-hero-art .am-hero-label small{font-size:11px;line-height:1.5}
.am-hero-art .am-hero-label .am-hero-index{font-size:12px}
.am-hero-editorial-note{margin:8px 0 0;font:400 12px/1.55 system-ui,sans-serif;color:#c3d0c3;max-width:300px}
.am-hero-featured-link{display:inline-flex;align-items:center;min-height:46px;margin-top:8px;
 font:700 12px/1.3 system-ui,sans-serif;color:#f1d8ac;text-decoration:none;
 text-underline-offset:5px;letter-spacing:.02em}
.am-hero-featured-link:hover{text-decoration:underline}
.am-hero-featured-link:focus-visible,.am-hero-zoom:focus-visible,.am-hero-option:focus-visible,
.am-story-zoom:focus-visible,.am-story-link:focus-visible{outline:3px solid #e2bf7f;outline-offset:3px}
.am-hero-picker{position:absolute;bottom:10px;left:0;right:0;z-index:3;
 display:flex;align-items:stretch;gap:9px;max-width:100%;
 overflow-x:auto;overscroll-behavior-x:contain;scrollbar-width:thin;padding:5px 5px 9px;
 scroll-padding-left:5px}
.am-hero-option{flex:0 0 auto;min-height:62px;display:flex;align-items:center;gap:9px;
 background:#122b20e5;border:1px solid #82938477;color:#e8e8dc;border-radius:3px;
 padding:5px 10px 5px 5px;cursor:pointer;min-width:118px;max-width:165px;
 font:600 11px/1.2 system-ui,sans-serif;transition:border-color .2s,background .2s}
.am-hero-option[aria-pressed="true"]{background:#f9f4e8;color:#1b3425;border-color:#e5c186}
.am-hero-option:hover{border-color:#e5c186}
.am-hero-option-photo{display:grid;place-items:center;width:50px;height:52px;flex:none;
 border-radius:2px;background:#f5f3ec;overflow:hidden}
.am-hero-option-photo img{height:100%;width:100%;object-fit:contain;mix-blend-mode:multiply}
.am-hero-option-fallback{color:#314d38;font:700 13px Georgia,serif}
.am-hero-zoom{z-index:3;position:absolute;right:0;top:27px;min-height:44px;
 padding:10px 14px;background:#fcf8eb;box-shadow:0 5px 30px #0c1a1780;
 border:1px solid #eadbbf;color:#1d3929;cursor:zoom-in;
 font:700 11px/1.2 system-ui,sans-serif;letter-spacing:.02em}
.am-hero-zoom:hover{background:#f3dfb9}
.am-hero-zoom[hidden]{display:none}

/* Product photography lookbook: one exact photo per named model,
   not faux lifestyle photography or a collection of scraped competitors' images. */
.am-editorial-gallery{background:#eee9de;padding:84px 0 94px;color:#1a3023;border-top:1px solid #dccfb9}
.am-editorial-head{display:flex;align-items:end;justify-content:space-between;gap:22px;margin-bottom:30px}
.am-editorial-head .overline{font-size:10px;color:#92774f}
.am-editorial-head h2{font:400 clamp(35px,4.4vw,62px)/1.12 Georgia,serif;
 letter-spacing:-.042em;max-width:700px;margin:14px 0 0}
.am-editorial-head h2 em{font-weight:400;color:#95754b}
.am-editorial-head>p{max-width:305px;color:#5c6b5e;font:400 13px/1.75 system-ui,sans-serif;margin:0}
.am-editorial-grid{display:grid;grid-template-columns:1.1fr 1fr 1fr;gap:18px}
.am-story-card{background:#faf8f2;border:1px solid #d8d0c3;min-width:0;display:flex;flex-direction:column;
 box-shadow:0 8px 35px #17251d08;transition:box-shadow .23s ease,transform .23s ease}
.am-story-card:hover{transform:translateY(-4px);box-shadow:0 20px 40px #17251d1b}
.am-story-media{position:relative;min-width:0;min-height:355px;height:clamp(350px,35vw,460px);
 overflow:hidden;display:grid;place-items:center;background:
 radial-gradient(ellipse 70% 65% at 50% 38%,#ffffff,#e8e6db 80%)}
.am-story-card:nth-child(2) .am-story-media{background:radial-gradient(ellipse 75% 70% at 50% 35%,#fffdfa,#dce8e2)}
.am-story-card:nth-child(3) .am-story-media{background:radial-gradient(ellipse 75% 70% at 50% 35%,#ffffff,#e4e4e7)}
.am-story-img{width:100%;height:100%;max-width:100%;max-height:100%;object-fit:contain;
 padding:clamp(12px,2.5vw,32px);box-sizing:border-box;mix-blend-mode:multiply;
 filter:drop-shadow(4px 16px 14px #25372d18);transition:transform .42s ease}
.am-story-card:hover .am-story-img{transform:scale(1.045)}
.am-story-zoom{position:absolute;bottom:15px;right:15px;min-height:44px;
 padding:11px 15px;border:1px solid #dacfb8;background:#fffdf5f2;color:#274a35;
 font:700 11px/1.2 system-ui,sans-serif;cursor:zoom-in}
.am-story-zoom:hover{background:#234936;color:#fff}
.am-story-photo-fallback{font:500 14px/1.5 system-ui,sans-serif;color:#536456}
.am-story-copy{display:flex;flex-direction:column;flex:1;padding:27px 25px 29px}
.am-story-kicker{font:700 10px/1.4 system-ui,sans-serif;letter-spacing:.15em;color:#8d764c;margin:0 0 15px}
.am-story-copy h3{font:400 clamp(23px,2.5vw,34px)/1.19 Georgia,serif;
 letter-spacing:-.025em;color:#182e20;min-height:2.5em;margin:0 0 13px}
.am-story-desc{font:400 13px/1.75 system-ui,sans-serif;color:#58665c;margin:0 0 15px;flex:1}
.am-story-fact{font:650 11px/1.55 system-ui,sans-serif;color:#36503c;padding:13px 0;border-top:1px solid #ddd8cc;
 border-bottom:1px solid #ddd8cc;margin:0 0 15px}
.am-story-link{font:700 12px/1.55 system-ui,sans-serif;color:#28583e;text-decoration:none;
 display:inline-flex;align-items:center;min-height:44px;align-self:start;text-underline-offset:4px}
.am-story-link:hover{text-decoration:underline}
@media(max-width:1050px){
 .am-hero-art{height:570px}
 .am-hero-art .am-hero-watch{top:27px;height:390px;margin-top:0}
 .am-hero-art .am-hero-label{bottom:101px}
 .am-hero-picker{gap:6px}
 .am-hero-option{min-width:101px;max-width:135px;padding-right:6px}
 .am-hero-option-photo{width:44px;height:48px}
 .am-editorial-grid{gap:12px}
 .am-story-media{height:340px;min-height:315px}
 .am-story-copy{padding:22px 19px 23px}
}
@media(max-width:940px){
 .aff-hero .aff-copy{padding-bottom:4px}
 .am-hero-art{height:525px;width:100%;margin:0 auto}
 .am-hero-art .am-hero-watch{top:18px;height:355px;margin-top:0}
 .am-hero-art .am-hero-label{bottom:109px;right:4px}
 .am-editorial-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
 .am-story-card:first-child{grid-row:span 2}
 .am-story-card:first-child .am-story-media{height:540px}
 .am-story-card:first-child .am-story-copy{min-height:260px}
 .am-editorial-head{align-items:start;flex-direction:column}
}
@media(max-width:680px){
 .aff-hero:before{font-size:125px;bottom:10%}
 .am-hero-art{height:440px;min-height:440px}
 .am-hero-art .am-hero-watch{top:14px;height:265px;margin-top:0}
 .am-hero-art .am-hero-watch img.am-hero-real-photo{filter:drop-shadow(12px 15px 14px #0008)}
 .am-hero-art:before{inset:2% 11% 19%;box-shadow:0 0 0 30px #e9d9ac08}
 .am-hero-art .am-hero-label{left:4px;right:auto;bottom:86px;max-width:min(340px,calc(100% - 8px));min-width:0;padding:11px 14px 9px;text-align:left}
 .am-hero-art .am-hero-label strong{font-size:16px}
 .am-hero-art .am-hero-label small{font-size:10px}
 .am-hero-editorial-note{display:none}
 .am-hero-featured-link{margin-top:0;min-height:36px}
 .am-hero-picker{bottom:0;gap:7px}
 .am-hero-option{min-width:95px;max-width:118px;min-height:58px;gap:5px;font-size:10px}
 .am-hero-option-photo{width:42px;height:45px}
 .am-hero-zoom{right:6px;top:18px}
 .am-editorial-gallery{padding:54px 0 58px}
 .am-editorial-head h2{font-size:clamp(34px,9vw,46px)}
 .am-editorial-grid{display:grid;grid-auto-flow:column;grid-auto-columns:min(82vw,350px);
  grid-template-columns:none;gap:12px;overflow-x:auto;scroll-snap-type:x mandatory;
  overscroll-behavior-x:contain;scrollbar-width:thin;padding:3px 4px 13px}
 .am-story-card,.am-story-card:first-child{grid-row:auto;scroll-snap-align:center}
 .am-story-card:first-child .am-story-media,.am-story-media{height:340px;min-height:340px}
 .am-story-card:first-child .am-story-copy{min-height:auto}
 .am-story-copy h3{min-height:0}
}
@media(prefers-reduced-motion:reduce){
 .am-hero-art:before,.am-hero-art .am-hero-watch img.am-hero-real-photo,
 .am-story-card,.am-story-img,.am-hero-option{transition:none!important}
 .am-story-card:hover{transform:none}
 .am-story-card:hover .am-story-img{transform:none}
}

'use strict';
/**
 * Atelier Montres — original photographic editorial experience.
 * References: Tissot's product-gallery clarity; Chrono24's photographic
 * discovery; 60fps.design motion restraint (ideas only, no copied assets).
 * Uses ONLY the existing model-specific WebP assets with owner-declared rights.
 * No generated substitute pretending to be a manufacturer's packshot.
 */
(() => {
  const featured=[
    {id:'citizen-tsuyosa',name:'Tsuyosa',theme:'jade',note:'Un vert de cadran qui ne passe pas inaperçu.',kicker:'01 · SPORT CHIC'},
    {id:'tissot-prx-quartz',name:'PRX Quartz',theme:'blue',note:'Lignes intégrées, allure graphique et mouvement quartz.',kicker:'02 · DESIGN'},
    {id:'orient-bambino',name:'Bambino 38',theme:'ivory',note:'Une vue du fond de boîte laisse découvrir sa mécanique.',kicker:'03 · CLASSIQUE'},
    {id:'casio-mtp-b145',name:'MTP-B145',theme:'steel',note:'Un format compact et une silhouette sans détour.',kicker:'04 · ESSENTIEL'}
  ];
  const editorial=[
    {id:'seiko-5',label:'Mécanique sportive',index:'01',description:'Automatique et cadran lisible : une référence pensée pour le quotidien.'},
    {id:'orient-bambino',label:'La mécanique côté fond',index:'02',description:'Une photographie réelle du dos du boîtier : découvrez le mécanisme visible de cette Bambino.'},
    {id:'tissot-prx-quartz',label:'Design intégré',index:'03',description:'Une silhouette seventies revisitée dans une montre quartz contemporaine.'}
  ];
  const node=(tag,cls,content)=>{
    const e=document.createElement(tag);
    if(cls)e.className=cls;
    if(content!==undefined)e.textContent=content;
    return e;
  };
  const local=p=>{
    const t=p?.photoReview;
    if(!p||!t||t.publicUsageApproved!==true||
      t.localUrl!=='./assets/watches/'+p.id+'.webp')return null;
    // The catalogue is verified separately; do not load arbitrary remote URLs.
    return t.localUrl+(typeof t.localSha256==='string'&&/^[a-f0-9]{64}$/i.test(t.localSha256)
      ?'?v='+t.localSha256.slice(0,12):'');
  };
  // Match the catalogue's SHA-versioned, locally generated WebP derivatives.
  // Never request a derivative for an unapproved or too-small original.
  const responsive=(p)=>{
    const t=p?.photoReview,w=t?.localWidth;
    if(t?.publicUsageApproved!==true||t.localUrl!=='./assets/watches/'+p.id+'.webp'||
       !Number.isInteger(w)||w<=480)return '';
    const version=typeof t.localSha256==='string'&&/^[a-f0-9]{64}$/i.test(t.localSha256)
      ?'?v='+t.localSha256.slice(0,12):'';
    const variants=[480,800].filter(size=>size<w).map(size=>
      './assets/watch-responsive/'+p.id+'-'+size+'.webp'+version+' '+size+'w');
    return [...variants,t.localUrl+version+' '+w+'w'].join(', ');
  };
  const applyResponsive=(img,p,sizes)=>{
    const set=responsive(p);
    if(set){img.srcset=set;img.sizes=sizes;}
    if(Number.isInteger(p.photoReview?.localWidth)&&Number.isInteger(p.photoReview?.localHeight)){
      img.width=p.photoReview.localWidth;img.height=p.photoReview.localHeight;
    }
  };
  const tryOriginal=(img,url,onFailure)=>{
    if(img.hasAttribute('srcset')){
      img.removeAttribute('srcset');img.removeAttribute('sizes');
      img.src=url;return;
    }
    onFailure();
  };
  const vector=(target,p)=>{
    target.replaceChildren();
    target.classList.remove('am-hero-real');
    target.removeAttribute('aria-busy');
    window.AtelierWatch?.render(target,p);
  };
  const openViewer=(catalogue,id)=>window.AtelierPhoto?.open(catalogue,id);
  function init(catalogue){
    if(!Array.isArray(catalogue)||!catalogue.length)return;
    const byId=new Map(catalogue.map(p=>[p.id,p]));
    const stage=document.getElementById('heroWatch');
    const picker=document.getElementById('heroVariants');
    const number=document.getElementById('heroEditorialIndex');
    const title=document.getElementById('heroEditorialTitle');
    const provenance=document.getElementById('heroEditorialSource');
    const zoom=document.getElementById('heroEditorialZoom');
    const featuredLink=document.getElementById('heroEditorialLink');
    const line=document.getElementById('heroEditorialNote');
    const scene=document.querySelector('.am-hero-art');
    const curated=featured.map(entry=>({...entry,product:byId.get(entry.id)})).filter(x=>x.product);
    let request=0;
    if(stage&&picker&&curated.length){
      const controls=curated.map((item,i)=>{
        const b=node('button','am-hero-option');
        b.type='button';
        b.dataset.watchId=item.id;
        b.setAttribute('aria-label','Sélectionner '+item.name+' : photographie de '+item.product.brand+' '+item.product.model);
        b.setAttribute('aria-pressed','false');
        const pic=node('span','am-hero-option-photo');
        const url=local(item.product);
        if(url){
          // The 200px local WebP is a faithful downscale of the same watch.
          // The original high-resolution photograph is still used in the hero,
          // product page and full-screen photo viewer.
          const thumbnail='./assets/watch-thumbs/'+item.id+'.webp';
          const img=node('img');img.alt='';img.width=65;img.height=65;
          img.loading='eager';img.decoding='async';
          let triedOriginal=false;
          img.onerror=()=>{
            if(!triedOriginal){triedOriginal=true;img.src=url;return;}
            img.remove();
            pic.append(node('span','am-hero-option-fallback',item.name.slice(0,2).toUpperCase()));
          };
          pic.append(img);img.src=thumbnail;
        } else pic.append(node('span','am-hero-option-fallback',item.name.slice(0,2).toUpperCase()));
        b.append(pic,node('span','am-hero-option-name',item.name));
        b.addEventListener('click',()=>select(i));
        b.addEventListener('keydown',event=>{
          if(!['ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;
          event.preventDefault();
          const next=event.key==='Home'?0:event.key==='End'?controls.length-1:
            (i+(event.key==='ArrowRight'?1:-1)+controls.length)%controls.length;
          controls[next].focus();select(next);
        });
        return b;
      });
      picker.replaceChildren(...controls);
      const select=i=>{
        const entry=curated[i],p=entry.product;
        if(!p)return;
        const token=++request;
        controls.forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));
        if(number)number.textContent=String(i+1).padStart(2,'0')+' / '+String(curated.length).padStart(2,'0');
        if(title)title.textContent=p.brand.toUpperCase()+' / '+entry.name.toUpperCase();
        if(line)line.textContent=entry.note;
        if(featuredLink){featuredLink.href='./montre.html?id='+encodeURIComponent(p.id);featuredLink.textContent='Explorer '+p.brand+' '+entry.name+' ↗';}
        if(scene)scene.dataset.editorialTone=entry.theme;
        stage.setAttribute('aria-label','Photographie de '+p.brand+' '+p.model);
        const url=local(p);
        const fallback=()=>{
          if(token!==request)return;
          vector(stage,p);
          if(provenance)provenance.textContent='Illustration originale · photographie indisponible';
          if(zoom)zoom.hidden=true;
        };
        if(!url){fallback();return}
        const show=img=>{
          if(token!==request)return;
          if(!img.naturalWidth){fallback();return}
          stage.classList.add('am-hero-real');
          stage.removeAttribute('aria-busy');
          if(stage.firstElementChild!==img)stage.replaceChildren(img);
          if(provenance)provenance.textContent='Photographie du modèle exact · '+(p.id==='orient-bambino'?'vue du fond du boîtier':(p.photoReview.provider||p.brand));
          if(zoom){zoom.hidden=false;zoom.setAttribute('aria-label','Agrandir la photo de '+p.brand+' '+p.model);zoom.onclick=()=>openViewer(catalogue,p.id);}
        };
        // Render injects the genuine Citizen photo directly into static HTML,
        // before JavaScript loads. Reuse it without blanking an already-visible
        // LCP image or downloading it a second time.
        const existing=stage.querySelector('img.am-hero-real-photo');
        if(existing&&existing.getAttribute('src')===url){
          existing.onload=()=>show(existing);
          existing.onerror=fallback;
          if(existing.complete)show(existing);
          return;
        }
        const img=node('img','am-hero-real-photo');
        img.alt=p.brand+' '+p.model+' — photographie de la référence réelle';
        img.decoding='async';img.loading='eager';
        img.referrerPolicy='no-referrer';if(i===0)img.fetchPriority='high';
        img.onload=()=>show(img);
        applyResponsive(img,p,'(max-width: 680px) 84vw, (max-width: 940px) 78vw, 520px');
        img.onerror=()=>tryOriginal(img,url,fallback);
        stage.setAttribute('aria-busy','true');
        stage.replaceChildren(node('span','am-hero-loading','Chargement de la photographie…'));
        if(zoom)zoom.hidden=true;
        img.src=url;
      };
      select(0);
    }
    const section=document.getElementById('amEditorialGallery');
    const target=document.getElementById('amEditorialGrid');
    if(!section||!target)return;
    const cards=[];
    for(const item of editorial){
      const p=byId.get(item.id),url=local(p);
      if(!p||!url)continue;
      const card=node('article','am-story-card');
      card.dataset.watchId=p.id;
      const media=node('div','am-story-media');
      const image=node('img','am-story-img');
      image.src=url;image.loading='lazy';image.decoding='async';
      applyResponsive(image,p,'(max-width: 680px) 82vw, (max-width: 940px) 46vw, 32vw');
      image.alt='Photographie de '+p.brand+' '+p.model+' — référence exacte';
      image.onerror=()=>tryOriginal(image,url,()=>{
        image.remove();const fallback=node('div','am-story-photo-fallback','Photographie indisponible');
        media.prepend(fallback);zoom.hidden=true;
      });
      const zoom=node('button','am-story-zoom','Agrandir ↗');
      zoom.type='button';
      zoom.setAttribute('aria-label','Agrandir la photographie de '+p.brand+' '+p.model);
      zoom.addEventListener('click',()=>openViewer(catalogue,p.id));
      media.append(image,zoom);
      const copy=node('div','am-story-copy');
      const top=node('p','am-story-kicker',item.index+' / '+item.label.toUpperCase());
      const name=node('h3','',p.brand+' '+p.model);
      const desc=node('p','am-story-desc',item.description);
      const link=node('a','am-story-link','Découvrir le modèle ↗');
      link.href='./montre.html?id='+encodeURIComponent(p.id);
      const movementLabel={quartz:'Quartz',automatic:'Automatique','eco-drive':'Solaire'};
      const factual=node('p','am-story-fact',[
        p.specs?.diameter||'Diamètre à vérifier',
        p.specs?.movement||movementLabel[p.movement]||'Mouvement à vérifier'
      ].join(' · '));
      copy.append(top,name,desc,factual,link);
      card.append(media,copy);cards.push(card);
    }
    if(cards.length){
      target.replaceChildren(...cards);
      section.hidden=false;
    }
  }
  window.AtelierEditorial=Object.freeze({init});
})();

/*
 * Atelier Montres — product + adviser editorial system.
 * Original HTML/CSS patterns informed by star-list research (Mobbin, Recent,
 * Awwwards and 60fps). No copied third-party assets or runtime dependencies.
 * Applies ONLY to existing adviser, interactive product and SEO product pages.
 */
:root{
  --product-graphite:#172326;
  --product-graphite-soft:#273638;
  --product-porcelain:#faf8f3;
  --product-ivory:#f1ede5;
  --product-copper:#a97843;
  --product-champagne:#e5bf86;
  --product-text:#203331;
  --product-muted:#49605a;
  --product-border:#dcd6cb;
  --product-card:#fffcf7;
  --product-shadow:0 16px 44px rgba(22,38,36,.09);
  --product-radius:12px;
}
body.advisor-page,body:has(.detail-layout),body:has(.watch-product){
  background:var(--product-porcelain);color:var(--product-text)
}
