.design-art{height:280px;display:grid;place-items:center;position:relative;overflow:hidden}
.design-art:before{content:"";position:absolute;width:210px;height:210px;border:1px solid rgba(255,255,255,.3);border-radius:50%;transform:scale(1.5)}
.design-green{background:linear-gradient(145deg,#1d3a33,#13221c 65%,#627365)}
