.design-dial{position:relative;width:150px;height:150px;border-radius:50%;background:radial-gradient(circle at 33% 26%,var(--face-light),var(--face-dark) 80%);border:8px solid #d1c3a6;outline:2px solid #8c8474;box-shadow:0 0 0 16px rgba(7,10,8,.15),15px 18px 30px rgba(0,0,0,.37);transform:rotate(-15deg)}
.design-dial:before,.design-dial:after{content:"";position:absolute;left:50%;top:50%;transform-origin:bottom}
.design-dial:before{width:3px;height:48px;background:#f7e9cb;transform:translate(-50%,-100%) rotate(55deg)}
.design-dial:after{width:4px;height:34px;background:#f7e9cb;transform:translate(-50%,-100%) rotate(288deg)}
.design-dial .mark-top,.design-dial .mark-bottom{position:absolute;width:4px;height:14px;background:#f7e9cb;left:calc(50% - 2px)}
.design-dial .mark-top{top:12px}.design-dial .mark-bottom{bottom:12px}
.design-dial .centre{position:absolute;left:calc(50% - 5px);top:calc(50% - 5px);width:10px;height:10px;background:#e4c794;border-radius:50%;z-index:2}
.design-green .design-dial{--face-light:#40766c;--face-dark:#0b241c}
