.am-real-photo-stage{background:#f5f3ed!important;display:flex;align-items:center;justify-content:center;overflow:hidden;padding:22px}.am-real-photo-stage::before,.am-real-photo-stage::after{display:none!important}.am-real-product-photo{max-width:100%;width:100%;height:100%;max-height:560px;object-fit:contain;mix-blend-mode:multiply;filter:drop-shadow(0 16px 18px #1c30241a)}


/* Editorial discovery and honest product actions on genuine-watch detail pages. */
.detail-quick-actions{display:flex;flex-wrap:wrap;gap:9px;margin:10px 0 22px}
.detail-quick-actions button{border:1px solid #bfb69e;background:#fffdf8;color:#2b4838;padding:12px 16px;min-height:44px;font:650 12px system-ui,sans-serif;cursor:pointer;transition:background .16s ease}
.detail-quick-actions button[aria-pressed="true"]{background:#264835;color:#fff;border-color:#264835}
.detail-quick-actions button:hover{background:#e9ece4}
.detail-quick-actions button[aria-pressed="true"]:hover{background:#31553f}
.detail-quick-actions button:focus-visible,.detail-related-card:focus-visible,.detail-adjacent-link:focus-visible{outline:3px solid #b18d4d;outline-offset:3px}
.detail-adjacent{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:54px 0 0}
.detail-adjacent-link{min-height:75px;display:flex;flex-direction:column;justify-content:center;gap:7px;text-decoration:none;color:#23432f;border:1px solid #d6cebf;background:#f2f0e9;padding:14px 20px;min-width:0}
.detail-adjacent-link:nth-child(2){text-align:right}
.detail-adjacent-link span{font-size:11px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:#847250}
.detail-adjacent-link strong{font-size:13px;font-weight:650;overflow-wrap:anywhere;line-height:1.45}
.detail-adjacent-link:hover{background:#eae7dc;border-color:#bba174}
.detail-related{padding:65px 0 15px}
.detail-related-heading{display:grid;grid-template-columns:1.1fr .9fr;align-items:end;gap:30px;margin-bottom:27px}
.detail-related-heading h2{font:400 clamp(32px,4vw,49px)/1.14 Georgia,serif;letter-spacing:-.03em;margin:0}
.detail-related-heading>p{max-width:440px;color:#647165;font-size:13px;line-height:1.8}
.detail-related-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}
.detail-related-card{min-width:0;display:flex;flex-direction:column;text-decoration:none;background:#fffefa;border:1px solid #dfd9cd;color:#24412f;padding:12px 12px 18px;transition:transform .17s ease,box-shadow .17s ease}
.detail-related-card:hover{transform:translateY(-3px);box-shadow:0 16px 24px #1833241b}
.detail-related-photo{display:flex;height:230px;width:100%;background:radial-gradient(circle,#fdfbf7,#eeece4);justify-content:center;align-items:center;overflow:hidden}
.detail-related-photo img{width:100%;height:100%;object-fit:contain;mix-blend-mode:multiply;max-width:100%;max-height:100%}
.detail-related-empty{font-size:12px;color:#596d5e;text-align:center}
.detail-related-brand{margin:17px 8px 5px;font-size:10px;letter-spacing:.13em;font-weight:750;text-transform:uppercase;color:#99815a}
.detail-related-model{margin:0 8px 12px;font:400 21px/1.3 Georgia,serif;overflow-wrap:anywhere}
.detail-related-action{margin:auto 8px 0;font-size:12px;font-weight:650;color:#2a5c3f}
@media(max-width:760px){.detail-adjacent{margin-top:34px}.detail-related{padding:48px 0 0}.detail-related-heading{grid-template-columns:1fr;gap:0}.detail-related-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.detail-related-photo{height:185px}}
@media(max-width:470px){.detail-related-grid{grid-template-columns:1fr}.detail-related-photo{height:260px}.detail-related-card{padding:14px}.detail-adjacent{gap:7px}.detail-adjacent-link{padding:11px 10px}.detail-adjacent-link strong{font-size:11px}.detail-quick-actions button{flex:1}}
