/* Deep-linked product-to-product comparison, with generous touch targets. */
.detail-quick-actions .detail-compare{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;color:#254431;background:#f0ede3;border:1px solid #c7bba3;min-height:44px;padding:12px 16px;font:650 12px/1.4 system-ui,sans-serif;transition:background .18s ease}
.detail-quick-actions .detail-compare:hover{background:#e4e2d5}
.detail-quick-actions .detail-compare:focus-visible{outline:3px solid #b18d4d;outline-offset:3px}
@media(max-width:580px){.detail-quick-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.detail-quick-actions .detail-compare{grid-column:1/-1;width:100%;text-align:center}.detail-quick-actions button{padding:11px 9px}}
