/* Factual reasons for recommendations, no invented stock or prices. */
.detail-related-why{display:inline-flex;align-self:flex-start;border:1px solid #cfcdbd;border-radius:100px;padding:6px 10px;margin:0 8px 18px;background:#f0f2eb;color:#526e58;font:650 10px/1.4 system-ui,sans-serif}

/* Premium product storytelling on the primary, interactive watch pages.
   Four source-grounded facts, visible unknowns and responsive real photographs. */
.detail-facts-section{margin:23px 0 17px;padding:20px 22px 15px;background:#f2eee5;border:1px solid #ddd3c2;box-shadow:0 6px 23px #1c372009}
.detail-facts-caption{margin:0 0 14px;color:#887044;font:750 10px/1.4 system-ui,sans-serif;letter-spacing:.16em}
