.detail-visual{background:radial-gradient(ellipse at 50% 34%,#fdfcf8 3%,#eef0e8 58%,#e0e9df 100%);border:1px solid #dbe1d5;box-shadow:0 20px 60px #14332113;isolation:isolate}
.detail-visual::before{content:'';position:absolute;inset:17px;border:1px solid #ffffff8c;pointer-events:none}
.detail-artwork{filter:none;z-index:1}
