/* Visible provenance for the product's technical facts (not a copyright grant). */
.detail-evidence{margin:23px 0 0;padding:17px 19px;border:1px solid #d7dcca;background:#f1f4ed;color:#274532}
.detail-evidence strong{display:block;color:#1c3928;font:700 12px/1.5 system-ui,sans-serif;letter-spacing:.025em}
